//   - created_at: Creation time (WIB (UTC+7) DateTime, e.g. 2026-10-16T00:00:00.000Z = 16 Oct 2026 00:00 WIB; the Z suffix does not mean UTC, do not convert the time zone)
//   - visibility: Post visibility setting
//   - image: Author profile image URL (null if not set)
//   - name: Author display name (null if not set)
//   - verified: Whether the author is a verified account
//   - like: Number of likes
//   - favorite: Number of favorites
//   - comment: Number of comments
//   - is_like: true if you have liked the post
//   - is_favorite: true if you have favorited the post
//
// Categories: POST (general post), ARTICLE (article), VIDEO (video), STOCKPICK (stock pick), POLLING (poll)
//
// Notes:
// - The stock code and category must be uppercase (e.g. BBCA, STOCKPICK); unknown values return empty data
// - Only posts within your account's access scope are returned
//
// Path parameters:
//   - code: Kode saham untuk menampilkan postingan pada ruang diskusi saham tersebut. Required.
//   - category: Kategori postingan: `POST` = postingan umum, `ARTICLE` = artikel, `VIDEO` = video, `STOCKPICK` = rekomendasi saham, `POLLING` = polling. One of: POST, ARTICLE, VIDEO, STOCKPICK, POLLING. Required.
//
// HTTP: GET /posts/space/category/{code}/{category} (cache: default TTL).
func (s *PostsService) ListByStockCategory(ctx context.Context, code string, category PostsListByStockCategoryCategory, params PostsListByStockCategoryParams) (*PostsListByStockCategoryResponse, error) {
	var out *PostsListByStockCategoryResponse
	err := s.c.do(ctx, request{method: "GET", route: "/posts/space/category/{code}/{category}", path: "/posts/space/category/" + url.PathEscape(code) + "/" + url.PathEscape(string(category)), query: params.values(), body: nil, tier: tierDefault}, &out)
	return out, err
}

